	result, err := db.ExecContext(ctx, `
		UPDATE content_components
		SET section_type = COALESCE(section_type, $1)
		WHERE id = $2::uuid
		  AND is_active = true
		  AND section_type IS NULL
	`, sectionType, existingID)
	...
}

