func KnownAspectsSorted(knownSpecAspects map[string]bool) []string {
	aspects := make([]string, 0, len(knownSpecAspects))
	for a := range knownSpecAspects { aspects = append(aspects, a) }
	sort.Strings(aspects)
	return aspects
}

